-- V008 — MUTCD catalog seed (v3: 1,118 codes)
--
-- Sign codes and names from the FHWA Manual on Uniform Traffic Control Devices (MUTCD), 11th
-- edition — a work of the U.S. Government, in the public domain. Each row's `source` records the
-- list it was compiled from:
--   - ibis-signs-v1          a compiled list of MUTCD sign codes (W / D / M / I / S / OM series)
--   - fhwa-mutcd-11th-ch2b   MUTCD Chapter 2B, regulatory signs (R series)
--   - fhwa-mutcd-11th-ch2c   MUTCD Chapter 2C, warning signs (W) and object markers (OM)
--   - fhwa-mutcd-11th-ch2d   MUTCD Chapter 2D, guide signs (D) and route markers (M)
--
-- Where a code appears in more than one list, the chapter text wins.

ALTER TABLE assets.mutcd_codes ADD COLUMN series text;

